	updated: { icon: 'pencil-outline', tone: 'moderate' },
	status: { icon: 'sync-outline', tone: 'warning' },
	comment: { icon: 'chat-outline', tone: 'low' },
	note: { icon: 'document-outline', tone: 'low' },
	attachment: { icon: 'paperclip-outline', tone: 'low' },
	approval_requested: { icon: 'send-outline', tone: 'warning' },
	approved: { icon: 'circle-check-outline', tone: 'positive' },
	rejected: { icon: 'circle-close-outline', tone: 'critical' },
	completed: { icon: 'circle-check-outline', tone: 'positive' },
	badge_issued: { icon: 'id-outline', tone: 'positive' },
	badge_lost: { icon: 'flag-outline', tone: 'critical' },
	badge_suspended: { icon: 'lock-outline', tone: 'warning' },
	badge_reactivated: { icon: 'unlock-outline', tone: 'positive' },
	access_granted: { icon: 'key-outline', tone: 'positive' },
	access_revoked: { icon: 'circle-minus-outline', tone: 'critical' },
	access_denied: { icon: 'circle-close-outline', tone: 'critical' },
	door: { icon: 'building-outline', tone: 'info' },
	training: { icon: 'shield-check-outline', tone: 'positive' },
	visitor: { icon: 'user-plus-outline', tone: 'moderate' },
