		id: cellText(pick(item, map, 'id')) || `item-${i}`,
		kind,
		icon: iconOver || k.icon,
		tone: TONES.includes(toneOver) ? toneOver : k.tone,
		actor: cellText(pick(item, map, 'actor')),
		actorImage: cellText(pick(item, map, 'actorImage')),
		verb: cellText(pick(item, map, 'verb')),
		target: cellText(pick(item, map, 'target')),
		suffix: cellText(pick(item, map, 'suffix')),
		text: cellText(pick(item, map, 'text')),
		timeRaw: isObj(timeRaw) ? str(timeRaw.value) : str(timeRaw),
		timeDisplay: isObj(timeRaw) ? str(timeRaw.display_value) : '',
