 * line), the "Actor verb Target" sentence, the note bubble and the day headers —
 * no design-system component renders a vertical event timeline for arbitrary data
 * (now-activity-stream-connected reads one record's journal only).
 * ------------------------------------------------------------------ */

const sentence = (it) => {
	if (it.text && !it.verb && !it.target) return <span className="af-text">{it.actor ? <strong>{it.actor} </strong> : null}{it.text}</span>;
	return (
		<span className="af-text">
			{it.actor ? <strong>{it.actor}</strong> : null}
			{it.verb ? ` ${it.verb} ` : ' '}
			{it.target ? <strong>{it.target}</strong> : null}
			{it.suffix ? ` ${it.suffix}` : null}
			{it.text && (it.verb || it.target) ? <span className="af-text-extra">{` ${it.text}`}</span> : null}
		</span>
	);
};

const entry = (it, p, state, dispatch, isLast) => {
	const onItem = p.clickable ? () => dispatch('ACTIVITY_FEED_ITEM_CLICKED', { id: it.id, kind: it.kind, item: it.raw }) : null;
	/* The name is a real link when there is a url (new tab, middle-click works).
	 * Without one — or with openAttachments off — the default is cancelled:
	 * now-text-link renders <a href=""> and would otherwise RELOAD THE PAGE. */
	const linkOpens = (a) => p.openAttachments !== false && !!a.url;
	const onAtt = (a, viaLink) => (e) => {
