		if (!viaLink && linkOpens(a) && typeof window !== 'undefined') window.open(a.url, '_blank', 'noopener');
	};
	return (
		<li className={`af-item${p.clickable ? ' af-item--clickable' : ''}`} on-click={onItem || undefined}
			attrs={p.clickable ? { tabindex: '0', role: 'button' } : {}}
			on-keydown={p.clickable ? (e) => { if (e.target === e.currentTarget && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); onItem(); } } : undefined}>
			<div className="af-rail" aria-hidden="true">
