				{p.showConnector !== false && !isLast ? <span className="af-line" /> : null}
			</div>
			<div className="af-body">
				<div className="af-head">
					{p.showAvatars !== false && it.actor ? (
						<now-avatar className="af-avatar" size="sm" userName={it.actor} imageSrc={it.actorImage || undefined} hideTooltip={true} />
