				{it.details.length ? (
					<div className="af-box">
						<now-label-value-stacked
							align="vertical"
							size="md"
							items={it.details.map((d) => ({ label: d.label, value: { type: 'string', value: d.value } }))}
						/>
					</div>
				) : null}
				{it.note ? <div className="af-note">{it.note}</div> : null}
				{it.attachments.length ? (
					<div className="af-atts">
						{it.attachments.map((a) => (
							<div className="af-att">
								{a.thumbnail ? (
									<button type="button" className="af-thumb" aria-label={`Open ${a.name || 'attachment'}`} on-click={onAtt(a, false)}>
										<now-image src={a.thumbnail} alt={a.name || 'Attachment'} fit="cover" />
