	const items = asItems(p.items).map((raw, i) => normalizeItem(raw, i, p.fieldMap, p.kinds));
	const grouped = buildGroups(items, { order: p.order === 'asc' ? 'asc' : 'desc', group: !!p.groupByDay, now: state.now });
